WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM sessions), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN session_no >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_no_tier, CASE WHEN new_group_flag >= 1 THEN 'HIGH' ELSE 'LOW' END AS new_group_flag_tier, PERCENTILE_APPROX(session_no, ARRAY(0.25, 0.5, 0.75)) AS session_no_quartiles, MIN(started_at) AS first_seen FROM sessionized GROUP BY CASE WHEN session_no >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN new_group_flag >= 1 THEN 'HIGH' ELSE 'LOW' END
